Definition uv := CL5A.uv.
Lemma uv_eaddz : forall E e z, uv E (APC.eaddz e z) = (uv E e + z) mod 2 ^ 64.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S@0|600;!1,50!1+41!2'8#3#2!1,9#1!2'8#34!3'6,735!2';1!2'8#4#3|10;!2'>!1,?8!1,?0!2'<!2'=7#29!2';13!2'<!2'=;!2';159$z;R+2!3+:+2#1:!2'<#1'@!2'<!2'=;#19$E;R+0$e;R+1$z;R+2vd!6'326$b;R2!3+:+2!2';1#1:!6'3+2<=vd!6'3+2>$z;R+2!3+:+2!2'<!2'=7#19:vd!6'3+2?=!2,A+2?!2'<!2'=;!2'<#199!3'B#1;9!3+:+2!2'<!2'=;>9?!2';1!2'C1#1!1'D#1!3+:+2<?!2';16!2'E35!2'8#3!3'F,7#24!4'G#3,7#24!3+:+2!2'H#3!2'I#2#1!2'<!2'=!2'H#3#2#19").
Qed.
