Section EscapeOk.
Context {SCFG_P : ScfgP}.
Variable L : asan_layout.
Variable ar : asan_run.
Variable C : asan_statics_cells.
Variable HI : asan_iface.
Hypothesis HIok : PmHeapIfaceA.asan_iface_ok L ar C SCFG HI.
Hypothesis LAY : L5A.as0_layout L C.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps (hl_segs L) (@mkst fx R (Z_to_bv 64 pc) M (seg_rom (hl_segs L))) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom (hl_segs L))) -> PMSA.fp_ok fx -> PMSA.fp_ok fx'.
Variable CL : Z.                        (* [comment removed for export] *)
Hypothesis CL40 : CL <= 2 ^ 40.         (* [comment removed for export] *)
Abbreviation IC := PMLA.C_xasan.
Abbreviation RSEGS := (hl_segs L).
Hypothesis PUSHB_OK : PMESA.str_push_back_x_specA L ar HI CL PC_PUSHB.      (* [comment removed for export] *)
Hypothesis TOCP_OK : PMESA.to_codepoint_specA L ar HI IC PC_TOCP.           (* [comment removed for export] *)

Definition hid (P : Prop) : Prop := P.

(* [comment removed for export] *)
Definition esc_at (q : Z) (bs : list Z) : Prop :=
  PMESA.stransA L ar HI IC CL PC_ESCAPE PMESA.ESC_SCRA 0
      (fun LBo _ _ R M SK => PMSA.a0 R q /\ PMSA.a1 R (len bs) /\ PMSA.a2 R 0 /\ PMSA.a3 R 0 /\ PMSA.a4 R SK /\ L5.bytes_at (hl_segs L) M q bs /\ L5.defined M q (len bs) /\ PMSA.text_inA M LBo q (len bs))
      (fun R' pay => PMSA.a0 R' pay) (fun pay => pay = esc_len bs) (esc_len bs).

